'use strict';
// Generated by the UI-GATES arcade pipeline. Family implementations are spliced in at the marker.
const W = 640, H = 400, R = 8, SPEED = 360, HOLD = 0.8, WIN = 5, AI_SPEED = 250;

function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
function axisInfo(p) {
  return p.axis === 'y'
    ? { n: 'y', t: 'x', nv: 'vy', tv: 'vx', ns: 'h', ts: 'w' }
    : { n: 'x', t: 'y', nv: 'vx', tv: 'vy', ns: 'w', ts: 'h' };
}
function overlaps(ball, rect) {
  const cx = clamp(ball.x, rect.x, rect.x + rect.w), cy = clamp(ball.y, rect.y, rect.y + rect.h);
  return (ball.x - cx) ** 2 + (ball.y - cy) ** 2 <= ball.r * ball.r;
}

/*%%FAMILIES%%*/

function makeRng(seed) {
  let s = (seed >>> 0) || 1;
  return () => {
    s = (s + 0x6D2B79F5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// dir: +1 serves toward the right paddle, -1 toward the left.
function serve(state, dir) {
  const a = (state.rng() - 0.5) * 0.9;
  state.hold = HOLD;
  return { x: W / 2, y: H / 2, vx: Math.cos(a) * SPEED * dir, vy: Math.sin(a) * SPEED, r: R };
}

function createGame(seed) {
  const state = {
    W, H, WIN, rng: makeRng(seed), scoreL: 0, scoreR: 0, over: false, hold: 0,
    left: { x: 20, y: H / 2 - 35, w: 12, h: 70, axis: 'x', dir: 1 },
    right: { x: W - 32, y: H / 2 - 35, w: 12, h: 70, axis: 'x', dir: -1 },
    ball: null,
  };
  state.ball = serve(state, 1);
  return state;
}

function step(state, dt, input) {
  if (state.over) return;
  dt = Math.min(dt, 1 / 20);
  const L = state.left, Rp = state.right;
  L.y = clamp(input.paddleY - L.h / 2, 0, H - L.h);
  aiMove(Rp, state.ball, dt, H);
  if (state.hold > 0) { state.hold -= dt; return; }
  const b = state.ball, prev = { x: b.x, y: b.y };
  move(b, dt);
  wall(b, W, H);
  paddleHit(b, L, prev);
  paddleHit(b, Rp, prev);
  roundCheck(state);
}

if (typeof document !== 'undefined') {
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  canvas.width = W; canvas.height = H;
  let state = createGame(Date.now()), paddleY = H / 2, last = performance.now();
  const keys = {};
  const toY = clientY => { const r = canvas.getBoundingClientRect(); return (clientY - r.top) * (H / r.height); };
  canvas.addEventListener('mousemove', e => { paddleY = toY(e.clientY); });
  canvas.addEventListener('touchmove', e => { paddleY = toY(e.touches[0].clientY); e.preventDefault(); }, { passive: false });
  const restart = () => { if (state.over) state = createGame(Date.now()); };
  canvas.addEventListener('click', restart);
  addEventListener('keydown', e => { keys[e.key] = true; if (e.key === ' ' || e.key === 'Enter') restart(); });
  addEventListener('keyup', e => { keys[e.key] = false; });

  function draw() {
    ctx.fillStyle = '#0d0f1a'; ctx.fillRect(0, 0, W, H);
    ctx.strokeStyle = '#2a3050'; ctx.setLineDash([8, 10]);
    ctx.beginPath(); ctx.moveTo(W / 2, 0); ctx.lineTo(W / 2, H); ctx.stroke(); ctx.setLineDash([]);
    ctx.fillStyle = '#5ec8ff'; ctx.fillRect(state.left.x, state.left.y, state.left.w, state.left.h);
    ctx.fillStyle = '#ff5d73'; ctx.fillRect(state.right.x, state.right.y, state.right.w, state.right.h);
    ctx.beginPath(); ctx.arc(state.ball.x, state.ball.y, R, 0, Math.PI * 2); ctx.fillStyle = '#fff'; ctx.fill();
    ctx.fillStyle = '#9aa3c7'; ctx.font = 'bold 40px system-ui, sans-serif'; ctx.textAlign = 'center';
    ctx.fillText(state.scoreL, W / 2 - 60, 56); ctx.fillText(state.scoreR, W / 2 + 60, 56);
    if (state.over) {
      ctx.fillStyle = 'rgba(13,15,26,0.8)'; ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#fff'; ctx.font = 'bold 32px system-ui, sans-serif';
      ctx.fillText(state.scoreL >= WIN ? 'YOU WIN' : 'CPU WINS', W / 2, H / 2 - 10);
      ctx.font = '16px system-ui, sans-serif'; ctx.fillText('Click or press Space to play again', W / 2, H / 2 + 22);
    }
  }
  function frame(now) {
    const dt = (now - last) / 1000; last = now;
    if (keys.ArrowUp || keys.w) paddleY -= 480 * dt;
    if (keys.ArrowDown || keys.s) paddleY += 480 * dt;
    paddleY = clamp(paddleY, 0, H);
    step(state, dt, { paddleY });
    draw();
    requestAnimationFrame(frame);
  }
  window.__uig = { get state() { return state; }, step, createGame };
  requestAnimationFrame(frame);
}

if (typeof module !== 'undefined') {
  const has = f => (typeof f === 'function' ? f : undefined);
  module.exports = {
    W, H, R, SPEED, WIN, AI_SPEED, createGame, step, serve, overlaps,
    move: has(typeof move !== 'undefined' && move), wall: has(typeof wall !== 'undefined' && wall),
    paddleHit: has(typeof paddleHit !== 'undefined' && paddleHit),
    roundCheck: has(typeof roundCheck !== 'undefined' && roundCheck),
    aiMove: has(typeof aiMove !== 'undefined' && aiMove),
  };
}
